/*
 * 点击作者头像和名字会打开用户卡片，与 Discourse 一致，
 * 取代核心中鼠标悬停时出现的卡片。
 *
 * 鼠标移入或键盘聚焦时就开始预取资料：点击时卡片通常已经
 * 拿到全部数据，一次显示完整。
 */
import { override } from 'flarum/common/extend';
import CommentPost from 'flarum/forum/components/CommentPost';
import { openUserCard, prefetchUserCard } from './components/UserCardPopover';
import { topicSettings } from './ui';
const TRIGGERS = '.Post-side .Post-avatar, .PostUser-name a';
export default function installUserCard() {
  override(CommentPost.prototype, 'listenForCard', function (original) {
    if (!topicSettings.userCard()) return original();
    const prefetch = event => {
      const user = this.attrs.post.user();
      if (user && event.target.closest?.(TRIGGERS)) prefetchUserCard(user);
    };
    this.element.addEventListener('pointerover', prefetch);
    this.element.addEventListener('focusin', prefetch);

    // 在捕获阶段：点击在这里终止，先于头像的 Link 导航到个人资料。
    this.element.addEventListener('click', event => {
      const trigger = event.target.closest(TRIGGERS);
      if (!trigger || !this.element.contains(trigger)) return;

      // Ctrl/Cmd+点击仍然在新标签页打开个人资料。
      if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
      const user = this.attrs.post.user();
      if (!user) return;
      event.preventDefault();
      event.stopPropagation();

      // 卡片对齐到侧栏头像；在手机上它被隐藏，
      // 此时以头部头像作为锚点。
      const sideAvatar = this.element.querySelector('.Post-side .Post-avatar');
      const anchor = sideAvatar && sideAvatar.offsetParent !== null ? sideAvatar : trigger;
      openUserCard(user, anchor);
    }, true);
  });
}
flarum.reg.add('lcoy-roselle', 'forum/topic/userCard', installUserCard);