/*
 * 侧栏打开或关闭，如同 Discourse 的汉堡按钮。
 *
 * 平板及以上（≥ 768px，与 Discourse 相同）它会停靠在内容旁，读者的
 * 选择会写入 localStorage；在读者选择之前，使用管理员的
 * 默认值。在手机上它变成汉堡面板，覆盖在内容之上，
 * 每个页面开始时都是关闭的。
 */
import { forumBool } from './settings';
const STORAGE_KEY = 'lcoy.sidebarOpen';
const DOCKED_QUERY = '(min-width: 768px)';
export const SHELL_CLASS = 'Lcoy';
export const OPEN_CLASS = 'Lcoy--sidebarOpen';
export const OVERLAY_CLASS = 'Lcoy--sidebarOverlay';
let dockedChoice = null;
let overlayOpen = false;
function readStoredChoice() {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    return stored === null ? null : stored === '1';
  } catch {
    return null;
  }
}
export function isDocked() {
  return window.matchMedia(DOCKED_QUERY).matches;
}
export function isSidebarOpen() {
  if (!isDocked()) return overlayOpen;
  if (dockedChoice === null) {
    dockedChoice = readStoredChoice() ?? forumBool('lcoySidebarOpenDefault', true);
  }
  return dockedChoice;
}
export function applySidebarState() {
  const app = document.getElementById('app');
  if (!app) return;
  const overlay = !isDocked() && overlayOpen;
  app.classList.toggle(OPEN_CLASS, isSidebarOpen());
  app.classList.toggle(OVERLAY_CLASS, overlay);
  document.documentElement.classList.toggle('Lcoy--overlayLock', overlay);
}
export function toggleSidebar() {
  if (isDocked()) {
    dockedChoice = !isSidebarOpen();
    try {
      localStorage.setItem(STORAGE_KEY, dockedChoice ? '1' : '0');
    } catch {
      // 没有存储时，该选择仅在页面重新加载前有效。
    }
  } else {
    overlayOpen = !overlayOpen;
  }
  applySidebarState();
}

/** 关闭覆盖面板——在导航时或点击其外部时。 */
export function closeOverlaySidebar() {
  if (!overlayOpen) return;
  overlayOpen = false;
  applySidebarState();
}
export function watchViewport() {
  window.matchMedia(DOCKED_QUERY).addEventListener('change', () => {
    overlayOpen = false;
    applySidebarState();
  });
}

/** 覆盖面板打开时，点击面板外的链接或前进/后退都应关闭它。 */
export function watchSidebarNavigation() {
  document.addEventListener('click', event => {
    if (!overlayOpen) return;
    const link = event.target?.closest?.('a');
    if (link && !link.closest('#lcoy-sidebar')) closeOverlaySidebar();
  }, true);
  window.addEventListener('popstate', closeOverlaySidebar);
}
flarum.reg.add('lcoy-roselle', 'forum/utils/sidebarState', { SHELL_CLASS: SHELL_CLASS,OPEN_CLASS: OPEN_CLASS,OVERLAY_CLASS: OVERLAY_CLASS,isDocked: isDocked,isSidebarOpen: isSidebarOpen,applySidebarState: applySidebarState,toggleSidebar: toggleSidebar,closeOverlaySidebar: closeOverlaySidebar,watchViewport: watchViewport,watchSidebarNavigation: watchSidebarNavigation, });