/*
 * “有 N 条新回复”——读者停在主题中间时，realtime 送来新帖子后出现的
 * Discourse 横条。在主题末尾，flarum/realtime 会直接把帖子追加进 stream，
 * 横条不出现；在中间，它只更新计数，这时横条才提醒。
 */
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import { t } from '../../utils/settings';
export default class NewRepliesBar extends Component {
  view() {
    const {
      discussion,
      stream,
      page
    } = this.attrs;
    const count = discussion.commentCount() || 0;
    if (page.lcoySeenCount === undefined || stream.viewingEnd()) page.lcoySeenCount = count;
    const fresh = count - page.lcoySeenCount;
    if (fresh <= 0) return null;
    return m("div", {
      className: "LcoyNewReplies",
      role: "status"
    }, m("button", {
      type: "button",
      className: "LcoyNewReplies-button",
      onclick: () => {
        page.lcoySeenCount = count;
        stream.goToLast();
      }
    }, m(Icon, {
      name: "fas fa-arrow-down"
    }), t('topic.new_replies', {
      count: fresh
    })));
  }
}
flarum.reg.add('lcoy-roselle', 'forum/topic/components/NewRepliesBar', NewRepliesBar);