/*
 * Discourse 的 `user-stream-item`：48px 头像、作为链接的主题标题、
 * 下方的分类和日期以及正文开头。用于资料的帖子标签页
 *（帖子、点赞、提及、投票、已解决）以及“反应”标签页，
 * 后者会额外添加反应行（`extra`）。
 */
import app from 'flarum/forum/app';
import Avatar from 'flarum/common/components/Avatar';
import Link from 'flarum/common/components/Link';
import classList from 'flarum/common/utils/classList';
import { truncate } from 'flarum/common/utils/string';
import { discussionBadges } from '../utils/tags';
import { fullDate, mediumAge } from '../utils/dates';

/** 摘录的长度（Discourse 的 `excerpt`）。 */
const STREAM_EXCERPT = 300;
export default function streamItem(post, options = {}) {
  const discussion = post.discussion();
  const user = post.user();
  const createdAt = post.createdAt();
  return m("div", {
    className: classList('PostListItem LcoyStreamItem', options.className)
  }, m("div", {
    className: "LcoyStreamItem-header"
  }, user ? m(Link, {
    href: app.route.user(user),
    className: "LcoyStreamItem-avatar",
    tabindex: "-1",
    "aria-hidden": "true"
  }, m(Avatar, {
    user: user
  })) : m("span", {
    className: "LcoyStreamItem-avatar"
  }, m(Avatar, {
    user: null
  })), m("div", {
    className: "LcoyStreamItem-details"
  }, m("div", {
    className: "LcoyStreamItem-title"
  }, m(Link, {
    href: app.route.post(post)
  }, discussion ? discussion.title() : '')), m("div", {
    className: "LcoyStreamItem-meta"
  }, discussion && discussionBadges(discussion), createdAt && m("time", {
    className: "LcoyStreamItem-date",
    datetime: createdAt.toISOString(),
    title: fullDate(createdAt)
  }, mediumAge(createdAt))))), options.extra, m("div", {
    className: "LcoyStreamItem-excerpt"
  }, truncate(post.contentPlain() || '', STREAM_EXCERPT)));
}
flarum.reg.add('lcoy-roselle', 'forum/user/streamItem', streamItem);