/*
 * Discourse 的列表导航栏（Horizon 中的 `.list-controls`）：
 * 分类/标签下拉菜单、排序标签（最新、热门、
 * 新帖、未读、最佳……）、分类链接、操作按钮以及
 * "发起讨论"。滚动时固定在卡片顶部。
 *
 * 只替换 IndexPage 的 `toolbar` 项：扩展放入
 * viewItems/actionItems/toolbarItems 的内容仍在这里面。
 */
import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Dropdown from 'flarum/common/components/Dropdown';
import SelectDropdown from 'flarum/common/components/SelectDropdown';
import LinkButton from 'flarum/common/components/LinkButton';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import IndexPage from 'flarum/forum/components/IndexPage';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import listItems from 'flarum/common/helpers/listItems';
import classList from 'flarum/common/utils/classList';
import ItemList from 'flarum/common/utils/ItemList';
import { forumBool, t } from '../utils/settings';
import { categoriesRouteName, categoriesUrl, categorySymbol, currentTag, isTagsEnabled, primaryTags, secondaryTags, sortTags, tagSymbol } from '../utils/tags';
import { CORE_SORTS, activeSort, sortLabel } from './sorts';
import SelectKit from '../composer/SelectKit';
import { currentSortRoute, routeForSort } from './routes';
/** Discourse 没有作为标签的核心排序：放在 "更多" 菜单中。 */
const OVERFLOW_SORTS = ['oldest', 'az', 'za'];
function onIndex() {
  return app.current.matches(IndexPage);
}

/** 按指定排序方式的列表 URL，保留当前页面的标签/过滤器。 */
function sortHref(sort) {
  const index = onIndex();
  const params = index ? {
    ...app.search.state.params()
  } : {};
  let routeName = index ? app.current.get('routeName') || 'index' : 'index';

  // 在总列表中，标签指向 Discourse 的地址（/latest、/hot、
  // /top……），排序方式包含在路由本身中。
  const sortRoute = forumBool('lcoyListRoutes', false) ? routeForSort(sort) : null;
  if (sortRoute && (routeName === 'index' || currentSortRoute())) {
    delete params.sort;
    routeName = sortRoute;
  } else if (currentSortRoute()) {
    routeName = 'index';
    params.sort = sort;
  } else if (sort === app.search.state.defaultSort()) {
    delete params.sort;
  } else {
    params.sort = sort;
  }

  // 空参数只会弄脏 URL（"?q=&filter="）。
  Object.keys(params).forEach(key => {
    const value = params[key];
    if (value === undefined || value === '' || typeof value === 'object' && value && !Object.keys(value).length) delete params[key];
  });
  return app.route(routeName, params);
}

/** 工具栏下拉菜单的一行：一个标签或一个特殊选项。 */

/** Discourse 的 `max_tags_in_filter_list`：其余的会在过滤时出现。 */
const MAX_TAGS_IN_LIST = 30;

/** 超过此数量时，"无二级标签" 会变成子查询过多的查询。 */
const MAX_NEGATED_TAGS = 50;

/**
 * 标签的 URL，保留所选排序，与 Discourse 的下拉菜单
 * 相同。`filter` 进入查询（`filter[-tag][]=…`）：IndexPage 会把它
 * 传给 API，服务端也会在初始加载时使用它。
 */
function tagHref(tag, filter) {
  const sort = onIndex() ? app.search.state.params().sort : undefined;
  const params = sort ? {
    sort
  } : {};
  if (filter) params.filter = filter;
  return tag ? app.route('tag', {
    tags: tag.slug(),
    ...params
  }) : app.route('index', params);
}

/** 当前 URL 中被排除的标签（`filter[-tag]`），用于标记 "无……"/"不含……"。 */
function negatedSlugs() {
  if (!onIndex()) return [];
  const value = (app.search.state.params().filter || {})['-tag'];
  const list = Array.isArray(value) ? value : value && typeof value === 'object' ? Object.values(value) : value ? [value] : [];
  return list.flatMap(item => String(item).split(','));
}

/** 带所选分类的页眉：显示它的徽章，"父 ▪ 子" 不显示 —— 只有它本身。 */
function categoryHeader(tag, parent = null) {
  return m("span", {
    className: "LcoyNav-dropBadge"
  }, parent && !tag.icon() ? splitSymbol(tag, parent) : categorySymbol(tag), m("span", {
    className: "LcoyNav-dropName"
  }, tag.name()));
}

/** 没有图标的子分类所用的双色小方块。 */
function splitSymbol(tag, parent) {
  const symbol = categorySymbol(tag);
  if (symbol?.attrs) {
    symbol.attrs.className = classList(symbol.attrs.className, 'LcoyCategorySymbol--split');
    symbol.attrs.style = {
      ...(symbol.attrs.style || {}),
      '--category-parent-color': parent.color() || 'var(--lcoy-primary-medium)'
    };
  }
  return symbol;
}

/** "图标 名称 × N"（访客还会看到描述），与 `category-row` 相同。 */
function dropRowContent(row, symbols, showDescription) {
  const tag = row.tag;
  const count = tag.discussionCount();
  const description = symbols && showDescription ? tag.description() : null;
  return m("span", {
    className: "LcoyNav-dropRow"
  }, m("span", {
    className: "LcoyNav-dropStatus"
  }, symbols ? row.parent && !tag.icon() ? splitSymbol(tag, row.parent) : categorySymbol(tag) : tagSymbol(tag, 'LcoyNav-dropTagIcon'), m("span", {
    className: "LcoyNav-dropName"
  }, tag.name()), symbols && count > 0 && m("span", {
    className: "LcoyNav-dropCount"
  }, "\xD7 ", count)), description && m("span", {
    className: "LcoyNav-dropDesc"
  }, description));
}
export default class ListNavigation extends Component {
  view() {
    return (
      // 固定在顶部是可选项：Horizon 会固定，meta.discourse.org 不会。
      m("nav", {
        className: classList('LcoyNav', {
          'LcoyNav--sticky': forumBool('lcoyNavSticky', false)
        }),
        "aria-label": t('nav.label')
      }, m("div", {
        className: "LcoyNav-start"
      }, this.startItems().toArray()), m("div", {
        className: "LcoyNav-end"
      }, this.endItems().toArray()))
    );
  }
  startItems() {
    const items = new ItemList();
    const page = this.attrs.page;
    if (isTagsEnabled() && forumBool('lcoyNavDropdowns', true)) {
      items.add('dropdowns', m("div", {
        className: "LcoyNav-dropdowns"
      }, this.dropdownItems().toArray()), 100);
    }
    const tabs = this.tabs();
    const overflow = this.overflowTabs();
    items.add('tabs', m("ul", {
      className: "LcoyNav-tabs"
    }, tabs.map(tab => m("li", {
      className: classList('LcoyNav-tab', `LcoyNav-tab--${tab.key}`, {
        active: tab.active
      })
    }, m(Link, {
      href: tab.href,
      force: true,
      "aria-current": tab.active ? 'page' : undefined
    }, tab.label))), overflow.length > 0 && m("li", {
      className: "LcoyNav-tab LcoyNav-tab--more"
    }, this.overflowDropdown(overflow))), 90);

    // 在移动端，标签页变成一个选择器（"最新 ⇅"）。
    items.add('select', m("div", {
      className: "LcoyNav-select"
    }, this.compactSelect([...tabs, ...overflow])), 80);
    if (page) {
      // 扩展放在排序旁边的项（例如过滤器）。
      const view = page.viewItems();
      view.remove('sort');
      if (!view.isEmpty()) items.add('view', m("ul", {
        className: "LcoyNav-view"
      }, listItems(view.toArray())), 70);
      const toolbar = page.toolbarItems();
      toolbar.remove('view');
      toolbar.remove('action');
      if (!toolbar.isEmpty()) items.add('toolbar', m("div", {
        className: "LcoyNav-extra"
      }, toolbar.toArray()), 60);
    }
    return items;
  }
  endItems() {
    const items = new ItemList();
    const page = this.attrs.page;
    if (page) {
      const actions = page.actionItems();

      // 核心在移动端放在这里的放大镜会与页眉的重复。
      actions.remove('search');
      if (!actions.isEmpty()) items.add('actions', m("ul", {
        className: "LcoyNav-actions"
      }, listItems(actions.toArray())), 100);
    }

    // Discourse 只向已登录用户显示 "发起讨论"。
    if (app.session.user) items.add('newTopic', this.newTopicButton(), 50);
    return items;
  }

  /** 按 Discourse 顺序排列的标签页；扩展的排序方式排在 "最佳" 之后。 */
  tabs() {
    const sortMap = app.discussions.sortMap();
    const index = onIndex();
    const current = index ? activeSort() : null;
    const keys = Object.keys(sortMap);
    const ordered = ['relevance', 'latest', 'hot', 'newest', 'unread', 'top'].filter(key => keys.includes(key) && !this.overflowKeys().includes(key));
    const fromExtensions = keys.filter(key => !CORE_SORTS.includes(key) && !ordered.includes(key) && !this.overflowKeys().includes(key));
    const tabs = [...ordered, ...fromExtensions].map(key => ({
      key,
      label: sortLabel(key),
      href: sortHref(key),
      active: current === key
    }));

    // 在分类内部，Discourse 不显示 "分类" 标签。
    if (isTagsEnabled() && forumBool('lcoyNavCategoriesLink', true) && !currentTag()) {
      tabs.push({
        key: 'categories',
        label: t('nav.categories_link'),
        href: categoriesUrl(),
        active: app.current.get('routeName') === categoriesRouteName()
      });
    }
    return tabs;
  }

  /**
   * 放入 "更多" 菜单的排序方式。Discourse 的 "新帖" 是未查看主题
   * 的列表，只对已登录用户存在；对访客来说，
   * Flarum 的 "最新" 留在菜单中，标签页则是 Meta
   * 未登录状态下的那些（最新、热门、最佳、分类）。
   */
  overflowKeys() {
    return app.session.user ? OVERFLOW_SORTS : ['newest', ...OVERFLOW_SORTS];
  }
  overflowTabs() {
    const sortMap = app.discussions.sortMap();
    const current = onIndex() ? activeSort() : null;
    return this.overflowKeys().filter(key => key in sortMap).map(key => ({
      key,
      label: sortLabel(key),
      href: sortHref(key),
      active: current === key
    }));
  }
  overflowDropdown(tabs) {
    const active = tabs.find(tab => tab.active);
    return m(Dropdown, {
      className: classList('LcoyNav-more', {
        active: !!active
      }),
      buttonClassName: "Button Button--text LcoyNav-moreButton",
      menuClassName: "Dropdown-menu--right",
      label: active ? active.label : m(Icon, {
        name: "fas fa-ellipsis-h"
      }),
      caretIcon: active ? 'fas fa-caret-down' : '',
      accessibleToggleLabel: t('nav.more')
    }, tabs.map(tab => m(LinkButton, {
      href: tab.href,
      active: tab.active,
      icon: tab.active ? 'fas fa-check' : true
    }, tab.label)));
  }
  compactSelect(tabs) {
    return m(SelectDropdown, {
      buttonClassName: "Button Button--text LcoyNav-selectButton",
      caretIcon: "fas fa-discourse-chevron-expand",
      defaultLabel: t('nav.default'),
      accessibleToggleLabel: t('nav.sort_label')
    }, tabs.map(tab => m(LinkButton, {
      href: tab.href,
      active: tab.active,
      icon: tab.active ? 'fas fa-check' : true
    }, tab.label)));
  }
  dropdownItems() {
    const items = new ItemList();
    const tag = currentTag();

    // 在子分类页面上，第一个下拉菜单显示父分类，第二个
    // 显示子分类 —— 与 Discourse 中的 "支持 › 安装" 相同。
    const isCategory = !!tag && (tag.position() !== null || tag.isChild());
    const parent = tag && tag.isChild() ? tag.parent() || null : null;
    const category = isCategory ? parent || tag : null;
    const subcategory = isCategory && parent ? tag : null;
    const label = tag && !isCategory ? tag : null;
    const negated = negatedSlugs();
    const categories = primaryTags();
    if (categories.length) {
      const rows = [];
      if (category) rows.push({
        key: 'all',
        special: true,
        label: t('nav.remove_filter'),
        href: tagHref(null)
      });
      categories.forEach(item => rows.push({
        key: item.slug(),
        tag: item,
        href: tagHref(item),
        selected: item === category
      }));
      items.add('categories', this.drop({
        className: 'LcoyNav-drop--categories',
        selected: !!category,
        header: category ? categoryHeader(category) : t('nav.categories'),
        label: t('nav.categories'),
        rows,
        symbols: true
      }), 100);
    }
    const children = category ? sortTags((category.children() || []).filter(Boolean)) : [];
    if (category && children.length) {
      // "不含子标签"：父分类且不含任何子标签，使用 flarum/tags 的
      // 排除过滤器（`filter[-tag][]=子标签`，每个子标签一组，
      // 以便表示 "都不含" 而不是 "不全部含"）。
      const childSlugs = children.map(child => child.slug());
      const noSub = !subcategory && childSlugs.length > 0 && childSlugs.every(slug => negated.includes(slug));
      const rows = [];
      if (subcategory || noSub) rows.push({
        key: 'all',
        special: true,
        label: t('nav.remove_filter'),
        href: tagHref(category)
      });
      if (!noSub) rows.push({
        key: 'none',
        special: true,
        label: t('nav.no_subcategory'),
        href: tagHref(category, {
          '-tag': childSlugs
        })
      });
      children.forEach(child => rows.push({
        key: child.slug(),
        tag: child,
        href: tagHref(child),
        selected: child === subcategory,
        parent: category
      }));
      items.add('subcategories', this.drop({
        className: 'LcoyNav-drop--subcategories',
        selected: !!subcategory || noSub,
        header: subcategory ? categoryHeader(subcategory, category) : noSub ? t('nav.no_subcategory') : t('nav.subcategories'),
        label: t('nav.subcategories'),
        rows,
        symbols: true
      }), 90);
    }
    const labels = secondaryTags();
    if (labels.length) {
      // "不含二级标签"：不包含任何标签（分类除外，
      // 与 Discourse 相同）。标签过多时，查询会变得很重。
      const labelSlugs = labels.map(item => item.slug());
      const noTagsSupported = labelSlugs.length <= MAX_NEGATED_TAGS;
      const noTags = noTagsSupported && labelSlugs.every(slug => negated.includes(slug));
      const rows = [];
      const base = category ? subcategory || category : null;
      if (label || noTags) rows.push({
        key: 'all',
        special: true,
        label: t('nav.remove_filter'),
        href: tagHref(base)
      });
      if (noTagsSupported && !noTags) rows.push({
        key: 'none',
        special: true,
        label: t('nav.no_tags'),
        href: tagHref(base, {
          '-tag': labelSlugs
        })
      });
      labels.forEach(item => rows.push({
        key: item.slug(),
        tag: item,
        href: tagHref(item),
        selected: item === label
      }));
      items.add('tags', this.drop({
        className: 'LcoyNav-drop--tags',
        selected: !!label || noTags,
        header: label ? m("span", {
          className: "LcoyNav-dropBadge"
        }, tagSymbol(label, 'LcoyNav-dropTagIcon'), m("span", {
          className: "LcoyNav-dropName"
        }, label.name())) : noTags ? t('nav.no_tags') : t('nav.tags'),
        label: t('nav.tags'),
        rows,
        symbols: false,
        limit: MAX_TAGS_IN_LIST
      }), 80);
    }
    return items;
  }

  /**
   * Discourse 的 `category-drop`/`tag-drop`：带 "›" 的页眉打开后
   * 变成 "⌄"，主体中有 "搜索…" 和放大镜，特殊选项以
   * 强调色加粗显示，分类为 "图标 名称 × N"。
   */
  drop(options) {
    const {
      rows,
      limit
    } = options;
    // 分类描述仅对访客显示（Discourse 会向已有
    // 信任等级的账号隐藏它）。
    const showDescription = !app.session.user;
    const filtered = filter => {
      const needle = filter.trim().toLowerCase();
      const special = needle ? [] : rows.filter(row => row.special);
      let normal = rows.filter(row => !row.special && (!needle || (row.tag?.name() || '').toLowerCase().includes(needle)));
      if (limit && !needle) normal = normal.slice(0, limit);
      return [...special, ...normal];
    };
    return m(SelectKit, {
      className: classList('LcoyNav-drop', options.className, {
        'has-selection': options.selected
      }),
      header: options.header,
      caret: "fas fa-angle-right",
      caretOpen: "fas fa-angle-down",
      label: options.label,
      filterIcon: true,
      highlightSelected: true,
      placeholder: t('nav.search_placeholder'),
      emptyText: t('nav.no_results'),
      rows: filter => filtered(filter).map(row => ({
        key: row.key,
        selected: row.selected,
        title: row.tag?.name() || row.label,
        content: row.special ? m("span", {
          className: "LcoyNav-dropSpecial"
        }, row.label) : dropRowContent(row, options.symbols, showDescription)
      })),
      after: filter => limit && !filter.trim() && rows.filter(row => !row.special).length > limit ? m("div", {
        className: "LcoyNav-dropMore"
      }, t('nav.filter_for_more')) : null,
      onselect: key => {
        const row = rows.find(item => item.key === key);
        if (row) m.route.set(row.href);
      }
    });
  }
  newTopicButton() {
    const tag = currentTag();
    const canStart = !app.session.user || (tag?.canStartDiscussion ? tag.canStartDiscussion() : !!app.forum.attribute('canStartDiscussion'));
    const label = canStart ? t('nav.new_topic') : app.translator.trans('core.forum.index.cannot_start_discussion_button', {}, true);
    return m(Button, {
      icon: "fas fa-edit",
      className: "Button Button--primary LcoyNav-newTopic",
      "aria-label": label,
      title: label,
      disabled: !canStart,
      onclick: () =>
      // 复用核心的操作：打开编辑器（或登录），并让
      // flarum/tags 填入当前标签，它挂在该方法上。
      IndexSidebar.prototype.newDiscussionAction.call(IndexSidebar.prototype).catch(() => {})
    }, label);
  }
}
flarum.reg.add('lcoy-roselle', 'forum/list/ListNavigation', ListNavigation);