import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import classList from 'flarum/common/utils/classList';
const STORAGE_PREFIX = 'lcoy.sidebarSection.';
function readCollapsed(name) {
  try {
    return localStorage.getItem(STORAGE_PREFIX + name) === '1';
  } catch {
    return false;
  }
}

/**
 * 侧栏区域，标题栏使用小型大写字母，并有折叠箭头——
 * 即 Discourse 的“分类”和“标签”。
 */
export default class SidebarSection extends Component {
  collapsed = false;
  oninit(vnode) {
    super.oninit(vnode);
    this.collapsed = !!this.attrs.title && readCollapsed(this.attrs.name);
  }
  view(vnode) {
    const {
      name,
      title,
      onEdit,
      editLabel,
      editIcon
    } = this.attrs;
    const contentId = `lcoy-sidebar-section-${name}`;
    return m("section", {
      className: classList('LcoySidebar-section', `LcoySidebar-section--${name}`, {
        collapsed: this.collapsed
      })
    }, title && m("div", {
      className: "LcoySidebar-sectionHead"
    }, m("button", {
      type: "button",
      className: "LcoySidebar-sectionHeader",
      "aria-expanded": this.collapsed ? 'false' : 'true',
      "aria-controls": contentId,
      onclick: () => this.toggle()
    }, m(Icon, {
      name: "fas fa-angle-down",
      className: "LcoySidebar-sectionCaret"
    }), m("span", {
      className: "LcoySidebar-sectionTitle"
    }, title)), onEdit && m("button", {
      type: "button",
      className: "LcoySidebar-sectionEdit",
      "aria-label": editLabel,
      title: editLabel,
      onclick: onEdit
    }, m(Icon, {
      name: editIcon || 'fas fa-pencil'
    }))), m("ul", {
      className: "LcoySidebar-sectionContent",
      id: contentId
    }, vnode.children));
  }
  toggle() {
    this.collapsed = !this.collapsed;
    try {
      localStorage.setItem(STORAGE_PREFIX + this.attrs.name, this.collapsed ? '1' : '0');
    } catch {
      // 没有存储时，该选择仅在页面重新加载前有效。
    }
  }
}
flarum.reg.add('lcoy-roselle', 'forum/components/SidebarSection', SidebarSection);